import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static boolean nextPermutation(int[] idx) {
        int n = idx.length;
        for (int i = n - 1; i >= 1; i--) {
            if (idx[i] > idx[i - 1]) {
                int temp = idx[i];
                idx[i] = idx[i - 1];
                idx[i - 1] = temp;
                Arrays.sort(idx, i, n);
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int a = scanner.nextInt();
        int b = scanner.nextInt();

        int[] frames = new int[6];
        int[] idxs = new int[6];
        for (int i = 0; i < 6; i++) {
            if (i < 4) {
                frames[i] = a;
            } else {
                frames[i] = b;
            }
            idxs[i] = i;
        }

        int bestAnswer = 6;
        while (true) {
            int count = 0;
            int leftover = 0;
            for (int i = 0; i < 6; i++) {
                if (leftover < frames[idxs[i]]) {
                    count++;
                    leftover = n;
                }
                leftover -= frames[idxs[i]];
            }
            if (count < bestAnswer) {
                bestAnswer = count;
            }
            if (!nextPermutation(idxs)) {
                break;
            }
        }

        System.out.println(bestAnswer);
        scanner.close();
    }
}

